<?php ($editing=isset($page)); ?><form method="POST" action="<?php echo e($editing?route('admin.pages.update',$page):route('admin.pages.store')); ?>" class="rounded-lg border border-[#EBEFEA] bg-white p-[18px] grid gap-3 [&_label]:grid [&_label]:gap-1.5 [&_input]:rounded-md [&_input]:border [&_input]:border-[#DDE2DF] [&_input]:bg-white [&_input]:px-2.5 [&_input]:py-2 [&_input]:text-xs [&_textarea]:min-h-[100px] [&_textarea]:rounded-md [&_textarea]:border [&_textarea]:border-[#DDE2DF] [&_textarea]:bg-white [&_textarea]:px-2.5 [&_textarea]:py-2 [&_textarea]:text-xs [&_select]:rounded-md [&_select]:border [&_select]:border-[#DDE2DF] [&_select]:bg-white [&_select]:px-2.5 [&_select]:py-2 [&_select]:text-xs"><?php echo csrf_field(); ?> <?php if($editing): ?><?php echo method_field('PUT'); ?><?php endif; ?><label>Title<input name="title" value="<?php echo e(old('title',$editing?$page->title:'')); ?>" required></label><label>Slug<input name="slug" value="<?php echo e(old('slug',$editing?$page->slug:'')); ?>"></label><label>Body<textarea id="page-body" rows="18"><?php echo e(data_get($editing?$page->content:[],'blocks.0.data.text','')); ?></textarea><div id="page-content-hidden"></div></label><label>Status<select name="status"><option value="draft" <?php if(old('status',$editing?$page->status:'draft')==='draft'): echo 'selected'; endif; ?>>Draft</option><option value="published" <?php if(old('status',$editing?$page->status:'draft')==='published'): echo 'selected'; endif; ?>>Published</option></select></label><label>SEO Title<input name="seo_title" value="<?php echo e(old('seo_title',$editing?$page->seo_title:'')); ?>"></label><label>SEO Description<textarea name="seo_description"><?php echo e(old('seo_description',$editing?$page->seo_description:'')); ?></textarea></label><button class="inline-flex h-[38px] cursor-pointer items-center justify-center rounded-md border border-transparent px-3.5 text-xs font-medium no-underline transition bg-[#526A5A] text-white hover:bg-[#293C32]">Save Page</button></form><?php $__env->startPush('scripts'); ?><script>document.currentScript.closest?.('form');const f=document.getElementById('page-body')?.closest('form');f?.addEventListener('submit',()=>{document.getElementById('page-content-hidden').innerHTML='<input type="hidden" name="content[blocks][0][type]" value="paragraph"><input type="hidden" name="content[blocks][0][data][text]">';document.querySelector('#page-content-hidden input:last-child').value=document.getElementById('page-body').value;});</script><?php $__env->stopPush(); ?><?php /**PATH /Users/ferdy/project-fl/vet-cms/backend/resources/views/admin/pages/_form.blade.php ENDPATH**/ ?>